using System;
using System.IO;
using System.Collections.Generic;
using System.Security.Cryptography;
class InstallationCoreFixtures {
 sealed class Registry : ISceneBlockRegistryStore { public string Command; public string GetCommand(){return Command;} public void SetCommand(string value){Command=value;} public bool DeleteOwnedCommand(string expected){if(Command!=expected)return false;Command=null;return true;} }
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static string Hash(string path){using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
 static void Main(string[] args){try{Run(args);}catch(Exception e){Console.WriteLine("FAIL: "+e.Message);Environment.ExitCode=1;}} static void Run(string[] args){if(args.Length!=1)throw new Exception("Fresh workspace fixture path required");string root=Path.GetFullPath(args[0]);string workspace=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,".."));if(!root.StartsWith(workspace+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Fixture must be inside workspace");if(Directory.Exists(root))throw new Exception("Fixture already exists");Directory.CreateDirectory(root);var reg=new Registry();bool busy=false;var m=new SceneBlockInstallationManager(root,"2.8.0",v=>busy,reg,null);
 foreach(string v in new[]{"2.7.0","2.8.0"}){string d=Path.Combine(root,v);Directory.CreateDirectory(d);var hashes=new Dictionary<string,string>();foreach(string n in new[]{"node.exe","2026-10-23-protocol.vbs","2026-10-23-on-demand.mjs"}){string p=Path.Combine(d,n);File.WriteAllText(p,n);hashes.Add(n,Hash(p));}m.RecordManifest(v,hashes);}
 reg.Command=m.BuildCommand("2.7.0");Check(m.PlanRemoval(true).Files.Count==0,"registered old and current retained");reg.Command=m.BuildCommand("2.8.0");var plan=m.PlanRemoval(true);Check(plan.Files.Count==4,"old manifest exact plan");File.WriteAllText(Path.Combine(root,"2.7.0","unexpected.txt"),"preserve");Check(!m.Remove(plan).Success,"new file blocks stale plan");plan=m.PlanRemoval(true);busy=true;Check(!m.Remove(plan).Success,"busy blocks execution");busy=false;
 string modified=Path.Combine(root,"2.7.0","node.exe");File.AppendAllText(modified,"modified");Check(!m.Remove(plan).Success,"stale payload hash blocks execution");plan=m.PlanRemoval(true);Check(!plan.Files.Exists(f=>f.Path==modified),"modified payload preserved");var result=m.Remove(plan);Check(result.Partial&&File.Exists(modified)&&File.Exists(Path.Combine(root,"2.7.0","unexpected.txt")),"unknown and modified preserved");
 reg.Command="foreign";plan=m.PlanRemoval(false);Check(!plan.WillRemoveRegistration,"foreign registry preserved");reg.Command="other";Check(!m.Remove(plan).Success,"stale registration blocks");
 bool rejected=false;try{m.BuildCommand("../outside");}catch{rejected=true;}Check(rejected,"traversal denied");
 reg.Command=null;Check(m.Repair("2.8.0"),"complete repair");plan=m.PlanRemoval(false);var cancelled=m.Scan();Check(File.Exists(Path.Combine(root,"2.8.0","node.exe")),"cancel represented without remove");result=m.Remove(plan);Check(result.Success&&reg.Command==null,"owned full removal");Regression(root);Extra(root);Console.WriteLine("ALL AVAILABLE FIXTURES COMPLETED");}
static void Extra(string root){
string area=Path.Combine(root,"2026-10-25-extra");Directory.CreateDirectory(area);string install=Path.Combine(area,"AI");Directory.CreateDirectory(install);string outside=Path.Combine(area,"login-marker.txt");File.WriteAllText(outside,"unchanged");
var registry=new Registry();var trusted=new Dictionary<string,Dictionary<string,string>>();string legacy=Path.Combine(install,"2.6.0");Directory.CreateDirectory(legacy);var hashes=new Dictionary<string,string>();foreach(string n in new[]{"node.exe","2026-10-23-protocol.vbs","2026-10-23-on-demand.mjs"}){string f=Path.Combine(legacy,n);File.WriteAllText(f,n);hashes.Add(n,Hash(f));}trusted.Add("2.6.0",hashes);
var manager=new SceneBlockInstallationManager(install,"2.8.0",v=>false,registry,trusted);Check(manager.Scan()[0].Complete,"strong legacy recognized");var plan=manager.PlanRemoval(true);manager.Remove(plan);Check(!Directory.Exists(legacy)&&File.ReadAllText(outside)=="unchanged","legacy removed and outside login untouched");
Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"node.exe"),"unknown");Check(!manager.Scan()[0].Recognized,"weak legacy rejected");plan=manager.PlanRemoval(false);plan.Files.Add(new SceneBlockPlannedFile{Path=outside,ExpectedHash=Hash(outside)});Check(!manager.Remove(plan).Success&&File.Exists(outside),"tampered sibling plan denied");
foreach(string n in hashes.Keys)File.WriteAllText(Path.Combine(legacy,n),n);string nested=Path.Combine(legacy,"nested-link");var start=new System.Diagnostics.ProcessStartInfo("cmd.exe","/c mklink /J \""+nested+"\" \""+area+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=System.Diagnostics.Process.Start(start)){process.StandardOutput.ReadToEnd();process.StandardError.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0){Console.WriteLine("SKIP nested/root reparse: fixture creation denied by environment");return;}}Check(!manager.PlanRemoval(false).CanExecute,"nested reparse denied");Check(File.ReadAllText(outside)=="unchanged","reparse outside marker unchanged");Directory.Delete(nested,false);
bool rootRejected=false;string link=Path.Combine(area,"root-link");start.Arguments="/c mklink /J \""+link+"\" \""+install+"\"";using(var process=System.Diagnostics.Process.Start(start)){process.StandardOutput.ReadToEnd();process.StandardError.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0)throw new Exception("Cannot create root reparse fixture");}try{new SceneBlockInstallationManager(link,"2.8.0",v=>false,registry,null);}catch{rootRejected=true;}Check(rootRejected,"root reparse denied");Directory.Delete(link,false);
} static void Regression(string fixture){
 string root=Path.Combine(fixture,"2026-10-25-regression");string folder=Path.Combine(root,"2.8.0");Directory.CreateDirectory(folder);var hashes=new Dictionary<string,string>();foreach(string name in new[]{"node.exe","2026-10-23-protocol.vbs","2026-10-23-on-demand.mjs","2026-10-25-SceneBlock-Approval.exe"}){string path=Path.Combine(folder,name);File.WriteAllText(path,name);hashes.Add(name,Hash(path));}
 var registry=new Registry();bool throwBusy=false;var manager=new SceneBlockInstallationManager(root,"2.8.0",v=>{if(throwBusy)throw new IOException("busy detection failed");return false;},registry,null);manager.RecordManifest("2.8.0",hashes);var plan=manager.PlanRemoval(false);throwBusy=true;Check(manager.Scan()[0].Busy,"busy detector exception treated busy");Check(!manager.PlanRemoval(false).CanExecute,"busy detector exception blocks plan");Check(!manager.Remove(plan).Success&&File.Exists(Path.Combine(folder,"node.exe")),"busy detector exception blocks stale execution");throwBusy=false;
 string runtime=Path.Combine(folder,"runtime");Directory.CreateDirectory(runtime);File.WriteAllText(Path.Combine(runtime,"log.txt"),"one");var cleanup=manager.PlanRemoval(true);File.AppendAllText(Path.Combine(runtime,"log.txt"),"two");Check(manager.Remove(cleanup).Success,"retained runtime log does not invalidate cleanup");File.AppendAllText(Path.Combine(runtime,"log.txt"),"three");using(var locked=new FileStream(Path.Combine(runtime,"log.txt"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))Check(manager.PlanRemoval(false).CanExecute,"locked unknown runtime is not traversed");string approval=Path.Combine(folder,"2026-10-25-SceneBlock-Approval.exe");File.AppendAllText(approval,"changed");Check(!manager.Scan()[0].Complete,"modified noncritical payload incomplete");bool denied=false;try{manager.Repair("2.8.0");}catch(InvalidOperationException){denied=true;}Check(denied&&registry.Command==null,"modified noncritical repair refused");File.Delete(approval);Check(!manager.Scan()[0].Complete,"missing noncritical payload incomplete");denied=false;try{manager.Repair("2.8.0");}catch(InvalidOperationException){denied=true;}Check(denied&&registry.Command==null,"missing noncritical repair refused");string newer=Path.Combine(root,"2.10.0");Directory.CreateDirectory(newer);foreach(string name in hashes.Keys)File.WriteAllText(Path.Combine(newer,name),name);manager.RecordManifest("2.10.0",hashes);var oldCleanup=manager.PlanRemoval(true);Check(oldCleanup.Files.Count==0&&!oldCleanup.Directories.Contains(newer),"newer unregistered version excluded from old cleanup");manager.Remove(oldCleanup);Check(File.Exists(Path.Combine(newer,"node.exe")),"newer unregistered payload preserved");
 }}
